INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mao-zedong','毛泽东','prc','[]',NULL,NULL,1893,12,NULL,'month',1976,9,NULL,'month','["政治家","军事家"]','1921年参与创建中国共产党，1927年领导秋收起义，随后在井冈山建立根据地；长征中经1935年遵义会议逐渐取得党和红军领导权，1945年任中共中央主席。抗战后领导中共与国民党进行内战，1949年当选中央人民政府主席，同年10月1日宣布中华人民共和国成立。1954年当选国家主席，1959年不连任，继续任中共中央主席，1976年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/毛泽东"},{"label":"全国政协：毛泽东生平","url":"https://www.cppcc.gov.cn/2011/06/27/ARTI1309159125046101.shtml"}]',NULL,NULL,'国家主席','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('npc-standing-committee','全国人大常委会','prc','["人大常委会","全国人民代表大会常务委员会"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["机构"]','1975年1月17日四届全国人大一次会议修宪废除国家主席，改由全国人民代表大会常务委员会集体行使国家元首职权，至1983年6月18日六届全国人大一次会议选举李先念为国家主席。期间委员长为朱德（1975–1976）、叶剑英（1978–1983）；朱德逝世至叶剑英就任之间由宋庆龄等副委员长集体代理。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/全国人民代表大会常务委员会"}]',NULL,NULL,'全国人大常委会','[]');
